(() => {
  'use strict';
  const canvas = document.getElementById('world');
  const ctx = canvas.getContext('2d');
  const N = 23;
  const $ = (id) => document.getElementById(id);
  const catalog = {
    life: [
      {id:'villager', icon:'🧑', name:'Villager', copy:'Invite a new islander to find their own way.'},
      {id:'tree', icon:'🌲', name:'Pine tree', copy:'Grow a little shade and shelter.'},
      {id:'deer', icon:'🦌', name:'Forest deer', copy:'A gentle visitor for your quiet woods.'},
      {id:'house', icon:'🏡', name:'Little home', copy:'Give your islanders a place to gather.'},
      {id:'flowers', icon:'🌼', name:'Wildflowers', copy:'Scatter a splash of color across the meadow.'},
      {id:'erase', icon:'🧽', name:'Eraser', copy:'Clear a tile and make room for something new.'}
    ],
    land: [
      {id:'grass', icon:'🌱', name:'Meadow', copy:'Brush soft green grass over the island.'},
      {id:'water', icon:'💧', name:'Water', copy:'Carve a sparkling pond into the land.'},
      {id:'mountain', icon:'⛰️', name:'Mountain', copy:'Lift the land into a rocky little peak.'},
      {id:'sand', icon:'🏖️', name:'Sandy shore', copy:'Lay down a warm golden beach.'},
      {id:'forest', icon:'🌳', name:'Forest', copy:'Plant a whole patch of leafy woodland.'},
      {id:'lake', icon:'🫧', name:'Lake', copy:'Make a small pool for wildlife to drink.'}
    ],
    chaos: [
      {id:'meteor', icon:'☄️', name:'Meteor', copy:'A tiny cosmic surprise. Make a crater!' },
      {id:'lightning', icon:'⚡', name:'Lightning', copy:'Strike a tile and watch the sparks fly.'},
      {id:'fire', icon:'🔥', name:'Wildfire', copy:'Start a little fire. Rain will calm it down.'},
      {id:'rain', icon:'🌧️', name:'Rain cloud', copy:'Bring a shower to put out fires and help trees.'},
      {id:'volcano', icon:'🌋', name:'Volcano', copy:'Raise a fiery peak in the middle of your world.'},
      {id:'erase', icon:'🧽', name:'Eraser', copy:'Clear a tile and make room for something new.'}
    ]
  };
  const names = ['Mosslight Isle','Fernwhistle','Little Sol','Juniper Bay','Pebblehaven','Cloudberry'];
  let world, selectedCategory = 'life', selectedTool = 'villager', paused = false, speed = 1;
  let zoom = 1, panX = 0, panY = 0, dpr = 1, W = innerWidth, H = innerHeight;
  let tick = 0, day = 1, season = 0, lastTime = 0, simAccumulator = 0;
  let pointer = {x:-100,y:-100,cell:null}, isDrawing = false, isPanning = false, spaceDown = false, lastPointer = {x:0,y:0};
  let toastTimer, lastEvent = 0, renderTime = 0;
  const seasons = ['EARLY SUMMER','HIGH SUMMER','GOLDEN AUTUMN','QUIET WINTER','SOFT SPRING'];
  const palette = {water:'#59aca9',deep:'#438d91',sand:'#e5ce91',grass:'#93c77d',forest:'#69aa73',darkgrass:'#6fae70',rock:'#969e89',snow:'#dce4cb'};
  function rnd(seed){let t=seed>>>0;return()=>{t+=0x6D2B79F5;let x=t;x=Math.imul(x^x>>>15,x|1);x^=x+Math.imul(x^x>>>7,x|61);return((x^x>>>14)>>>0)/4294967296}}
  function makeWorld(){
    const r=rnd(Date.now()|0), tiles=Array.from({length:N},(_,x)=>Array.from({length:N},(_,y)=>({x,y,type:'water',h:0,tree:false,flowers:false,fire:0,crater:0})));
    const cx=(N-1)/2,cy=(N-1)/2;
    for(let x=0;x<N;x++)for(let y=0;y<N;y++){
      const dx=(x-cx)/9.6,dy=(y-cy)/8.8,dist=Math.sqrt(dx*dx+dy*dy);
      const wave=(r()-.5)*.16+Math.sin(x*1.35+y*.83)*.035+Math.cos(y*1.53-x*.57)*.035;
      if(dist < .94+wave){const edge=dist>.79+wave;tiles[x][y].type=edge?'sand':'grass';tiles[x][y].h=edge?1:1+Math.floor(Math.max(0,1-dist)*3.2+r()*.8);if(tiles[x][y].h>2&&r()<.32)tiles[x][y].type='rock';if(!edge&&r()<.14)tiles[x][y].flowers=true;}
    }
    const island={name:names[Math.floor(r()*names.length)],tiles,people:[],deer:[],homes:[],day:1,seed:Date.now(),happiness:96,crystals:0};
