  canvas.addEventListener('pointermove',e=>{const p=canvasPoint(e);pointer={...p,cell:pickCell(p.x,p.y)};if(isPanning){panX+=e.clientX-lastPointer.x;panY+=e.clientY-lastPointer.y;lastPointer={x:e.clientX,y:e.clientY};}else if(isDrawing&&pointer.cell&&(pointer.cell.x!==lastPointer.x||pointer.cell.y!==lastPointer.y)){applyTool(pointer.cell.x,pointer.cell.y);lastPointer={x:pointer.cell.x,y:pointer.cell.y};}});
  function endPointer(){isDrawing=false;isPanning=false;canvas.classList.remove('panning')}
  canvas.addEventListener('pointerup',endPointer);canvas.addEventListener('pointercancel',endPointer);canvas.addEventListener('contextmenu',e=>e.preventDefault());
  canvas.addEventListener('pointerleave',()=>{if(!isDrawing&&!isPanning)pointer={x:-100,y:-100,cell:null}});
  canvas.addEventListener('wheel',e=>{e.preventDefault();const old=zoom;zoom=Math.max(.65,Math.min(1.65,zoom*(e.deltaY<0?1.09:.92)));$('zoom-label').textContent=`${Math.round(zoom*100)}%`;if(old!==zoom){const p=canvasPoint(e);panX+=(p.x-W/2-panX)*(zoom/old-1);panY+=(p.y-H/2-panY)*(zoom/old-1);}}, {passive:false});
  document.addEventListener('keydown',e=>{if(e.code==='Space'){spaceDown=true;e.preventDefault()}if(e.key==='Escape')$('help-modal').hidden=true;if(e.key.toLowerCase()==='p')$('play-btn').click();if(e.key==='1'||e.key==='2'||e.key==='4'){document.querySelector(`.speed-button[data-speed="${e.key}"]`)?.click();}});
  document.addEventListener('keyup',e=>{if(e.code==='Space')spaceDown=false});
  document.querySelectorAll('.category-tab').forEach(b=>b.addEventListener('click',()=>{selectedCategory=b.dataset.category;document.querySelectorAll('.category-tab').forEach(t=>t.classList.toggle('active',t===b));drawTools()}));
  $('play-btn').addEventListener('click',()=>{paused=!paused;$('play-icon').textContent=paused?'▶':'Ⅱ';$('play-btn').title=paused?'Resume simulation':'Pause simulation';updateStats();showToast(paused?'Time paused':'And we are off!')});
  document.querySelectorAll('.speed-button').forEach(b=>b.addEventListener('click',()=>{speed=Number(b.dataset.speed);document.querySelectorAll('.speed-button').forEach(s=>s.classList.toggle('active',s===b));$('sim-speed-label').textContent=speed===1?'NORMAL SPEED':speed===2?'QUICKENED TIME':'TIME FLIES'}));
  $('zoom-in').onclick=()=>{zoom=Math.min(1.65,zoom*1.12);$('zoom-label').textContent=`${Math.round(zoom*100)}%`};$('zoom-out').onclick=()=>{zoom=Math.max(.65,zoom/1.12);$('zoom-label').textContent=`${Math.round(zoom*100)}%`};$('center-btn').onclick=()=>{zoom=1;panX=0;panY=0;$('zoom-label').textContent='100%'};
  $('new-world').addEventListener('click',()=>{world=makeWorld();tick=0;day=1;season=0;paused=false;$('play-icon').textContent='Ⅱ';$('season-label').textContent=seasons[0];$('day-label').textContent='DAY 01';$('event-log').innerHTML='';logEvent('✦','A brand new world begins');logEvent('🧑','Eight little islanders arrived');panX=0;panY=0;zoom=1;$('zoom-label').textContent='100%';showToast('A fresh little world is yours');updateStats()});
  $('reset-btn').addEventListener('click',()=>{tick=0;day=1;season=0;paused=false;world.day=1;for(const row of world.tiles)for(const t of row)t.fire=0;for(const p of world.people){p.tx=p.x;p.ty=p.y;p.mood=90}for(const d of world.deer){d.tx=d.x;d.ty=d.y} $('day-label').textContent='DAY 01';$('season-label').textContent=seasons[0];$('play-icon').textContent='Ⅱ';$('event-log').innerHTML='';logEvent('↺','The island began a new chapter');showToast('The day begins again');updateStats()});
  $('rename-world').addEventListener('click',()=>{const name=prompt('Give your little world a name:',world.name);if(name&&name.trim()){world.name=name.trim().slice(0,24);updateStats();showToast(`Welcome to ${world.name}`)}});
  $('help-btn').onclick=()=>{$('help-modal').hidden=false};$('close-help').onclick=$('start-playing').onclick=()=>{$('help-modal').hidden=true};$('help-modal').addEventListener('click',e=>{if(e.target===$('help-modal'))$('help-modal').hidden=true});
  let muted=true;$('sound-btn').addEventListener('click',()=>{muted=!muted;$('sound-icon').textContent=muted?'♪':'♫';showToast(muted?'Sound effects off':'Sound effects on')});
  function frame(now){const dt=Math.min(.1,(now-lastTime)/1000||0);lastTime=now;if(!paused){simAccumulator+=dt*speed;while(simAccumulator>=1){simulate();simAccumulator-=1;}}drawWorld(now);requestAnimationFrame(frame)}
  world=makeWorld();fitCanvas();drawTools();logEvent('✦','A quiet island waits for its story');logEvent('🧑','Eight little islanders arrived');updateStats();
  window.addEventListener('resize',fitCanvas);requestAnimationFrame(frame);
})();

