  const canvas=document.getElementById('world'),ctx=canvas.getContext('2d'),N=23,$=id=>document.getElementById(id);
  const catalog={life:[['villager','🧑','Villager','Invite a new islander to find their own way.'],['tree','🌲','Pine tree','Grow a little shade and shelter.'],['deer','🦌','Forest deer','A gentle visitor for your quiet woods.'],['house','🏡','Little home','Give your islanders a place to gather.'],['flowers','🌼','Wildflowers','Scatter a splash of color across the meadow.'],['erase','🧽','Eraser','Clear a tile and make room for something new.']],land:[['grass','🌱','Meadow','Brush soft green grass over the island.'],['water','💧','Water','Carve a sparkling pond into the land.'],['mountain','⛰️','Mountain','Lift the land into a rocky little peak.'],['sand','🏖️','Sandy shore','Lay down a warm golden beach.'],['forest','🌳','Forest','Plant a patch of leafy woodland.'],['lake','🫧','Lake','Make a small pool for wildlife to drink.']],chaos:[['meteor','☄️','Meteor','A tiny cosmic surprise. Make a crater!'],['lightning','⚡','Lightning','Strike a tile and watch the sparks fly.'],['fire','🔥','Wildfire','Start a fire. Rain will calm it down.'],['rain','🌧️','Rain cloud','Bring a shower to put out fires.'],['volcano','🌋','Volcano','Raise a fiery peak in your world.'],['erase','🧽','Eraser','Clear a tile and make room for something new.']]};
  const seasons=['EARLY SUMMER','HIGH SUMMER','GOLDEN AUTUMN','QUIET WINTER','SOFT SPRING'],names=['Mosslight Isle','Fernwhistle','Little Sol','Juniper Bay','Pebblehaven','Cloudberry'];
  let world,cat='life',tool='villager',paused=false,speed=1,zoom=1,panX=0,panY=0,dpr=1,W=innerWidth,H=innerHeight,tick=0,day=1,season=0,lastTime=0,acc=0,renderTime=0;
  let pointer={x:-100,y:-100,cell:null},drawing=false,panning=false,space=false,last={x:0,y:0},toastTimer;
  const rnd=seed=>()=>{seed|=0;seed=seed+0x6D2B79F5|0;let t=Math.imul(seed^seed>>>15,1|seed);t=t+Math.imul(t^t>>>7,61|t)^t;return((t^t>>>14)>>>0)/4294967296};
  function makeWorld(){const r=rnd(Date.now()|0),tiles=Array.from({length:N},(_,x)=>Array.from({length:N},(_,y)=>({x,y,type:'water',h:0,tree:false,flowers:false,fire:0,crater:0}))),cx=11,cy=11;
    for(let x=0;x<N;x++)for(let y=0;y<N;y++){const d=Math.hypot((x-cx)/9.6,(y-cy)/8.8),w=(r()-.5)*.16+Math.sin(x*1.35+y*.83)*.035+Math.cos(y*1.53-x*.57)*.035;if(d<.94+w){const edge=d>.79+w,t=tiles[x][y];t.type=edge?'sand':'grass';t.h=edge?1:1+Math.floor(Math.max(0,1-d)*3.2+r()*.8);if(t.h>2&&r()<.32)t.type='rock';if(!edge&&!t.tree&&r()<.14)t.flowers=true;}}
    const w={name:names[Math.floor(r()*names.length)],tiles,people:[],deer:[{x:8.5,y:8.4,tx:8.5,ty:8.4,walk:r()*8}],homes:[],day:1};
    const cells=[];for(let x=3;x<N-3;x++)for(let y=3;y<N-3;y++)if(tiles[x][y].type==='grass'&&tiles[x][y].h<=2)cells.push({x,y});for(let i=cells.length-1;i>0;i--){const j=Math.floor(r()*(i+1));[cells[i],cells[j]]=[cells[j],cells[i]];}for(let i=0;i<26&&i<cells.length;i++)tiles[cells[i].x][cells[i].y].tree=true;
    for(const [x,y] of [[10,11],[13,11],[11,13]])if(tiles[x][y].type==='grass')w.homes.push({x,y,level:1});
    const colors=['#e18b62','#e6bf6c','#82a9a0','#cd8291','#93b770','#dd9665','#7995c8','#d4a756'];for(let i=0;i<8;i++){let x=10+Math.floor(r()*5)-2,y=10+Math.floor(r()*5)-2;if(tiles[x][y].type!=='grass'){x=11;y=11;}w.people.push({x,y,tx:x,ty:y,name:['Milo','Pip','Fern','Otto','Wren','Clover','Theo','Moss'][i],mood:Math.floor(65+r()*34),color:colors[i],walk:r()*8,age:12});}return w;}
  function logEvent(icon,text){const el=document.createElement('div');el.className='log-item';el.innerHTML=`<span class="log-icon">${icon}</span><div><b>${text}</b><span class="log-time">JUST NOW</span></div>`;$('event-log').prepend(el);while($('event-log').children.length>3)$('event-log').lastElementChild.remove();}
  function toast(text){const e=$('toast');e.textContent=text;e.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>e.classList.remove('show'),2100)}
  function setTool(id){tool=id;document.querySelectorAll('.tool-button').forEach(b=>b.classList.toggle('selected',b.dataset.tool===id));const t=Object.values(catalog).flat().find(v=>v[0]===id);if(t){$('detail-icon').textContent=t[1];$('detail-name').textContent=t[2];$('detail-copy').textContent=t[3];$('hint-text').textContent=t[3];}}
  function drawTools(){const grid=$('tool-grid');grid.innerHTML='';catalog[cat].forEach(t=>{const b=document.createElement('button');b.className='tool-button'+(tool===t[0]?' selected':'');b.dataset.tool=t[0];b.innerHTML=`<span class="tool-emoji">${t[1]}</span><span class="tool-label">${t[2]}</span>`;b.title=t[3];b.onclick=()=>setTool(t[0]);grid.appendChild(b)});if(!catalog[cat].some(t=>t[0]===tool))setTool(catalog[cat][0][0]);}
  function fit(){const r=canvas.getBoundingClientRect();W=r.width;H=r.height;dpr=Math.min(devicePixelRatio||1,2);canvas.width=W*dpr;canvas.height=H*dpr;ctx.setTransform(dpr,0,0,dpr,0,0)}
  function met(){const mob=W<760,b=Math.max(15,Math.min(43,(mob?W-20:W-500)/N,(mob?H-290:H-220)/(N*.55)));return{tw:b*zoom,th:b*.52*zoom,step:b*.20*zoom,ox:W/2+panX,oy:H/2+panY+(mob?-17:4)}}
  function proj(x,y,h=0){const m=met();return{x:m.ox+(x-y)*m.tw/2,y:m.oy+(x+y-(N-1))*m.th/2-h*m.step}}
  function poly(p,c,stroke){ctx.beginPath();ctx.moveTo(p[0].x,p[0].y);for(let i=1;i<p.length;i++)ctx.lineTo(p[i].x,p[i].y);ctx.closePath();ctx.fillStyle=c;ctx.fill();if(stroke){ctx.strokeStyle=stroke;ctx.lineWidth=.65;ctx.stroke()}}
  function shade(hex,n){const c=parseInt(hex.slice(1),16);return`rgb(${Math.max(0,(c>>16)-n)},${Math.max(0,((c>>8)&255)-n)},${Math.max(0,(c&255)-n)})`}
  function ocean(t){const g=ctx.createLinearGradient(0,0,0,H);g.addColorStop(0,'#b7dfd7');g.addColorStop(.52,'#93ccc9');g.addColorStop(1,'#76b8b9');ctx.fillStyle=g;ctx.fillRect(0,0,W,H);for(let i=0;i<34;i++){const s=i*81.7,x=((s*7.31+Math.sin(t*.00015+i)*22)%W+W)%W,y=((s*4.77+Math.cos(t*.00012+i*2)*16)%H+H)%H;ctx.strokeStyle=`rgba(239,255,235,${.08+Math.sin(t*.001+i)*.035})`;ctx.beginPath();ctx.ellipse(x,y,5+(i*9)%13,1.2,0,0,7);ctx.stroke();}const m=met(),p=proj(11,11);ctx.save();ctx.translate(p.x,p.y+14*m.step);ctx.scale(1,.34);const s=ctx.createRadialGradient(0,0,10,0,0,N*m.tw*.34);s.addColorStop(0,'rgba(24,78,78,.2)');s.addColorStop(1,'rgba(24,78,78,0)');ctx.fillStyle=s;ctx.beginPath();ctx.ellipse(0,0,N*m.tw*.34,N*m.th*.9,0,0,7);ctx.fill();ctx.restore();}
